# ------------------------------------------------------------------------------------------------ measurement 1

def event_value(part):
    return ("R", "not") if part == "r_hear" else ("S", "stop")


TIE_TOL = 0.001          # package v0.6 15.2: score-level pairs closer than this count as ties (author 11-21: option A)


def group_eval(groups, rows_by, dec, sc=None, tol=0.0):
    """Per group: all versions right, follow of version 1 and of the others, within-group paired concordance
    (version 1 against each other version; event score = 1 - P(respond) or P(stop); decisions when no scores).
    tol: score-level pairs with |difference| < tol count 0.5 (v0.6 passes TIE_TOL; 0 keeps the earlier scripts)."""
    out = {}
    for g in groups:
        q, ev = event_value(g["part"])
        keys = [(g["unit"], v, g["k"]) for v in g["versions"]]
        if any(k not in dec or q not in dec[k] for k in keys):
            continue
        gold = [rows_by[(k[0], k[1])]["points"][0]["gold"][q] for k in keys]
        right = all(dec[k][q] == gd for k, gd in zip(keys, gold))
        fol = [dec[k][q] == ev for k in keys]
        if sc is not None and all(k in sc and q in sc[k] for k in keys):
            s = [(1 - sc[k][q]) if q == "R" else sc[k][q] for k in keys]
        else:
            s = [float(f) for f in fol]
        pair = {g["versions"][i]: (0.5 if s[0] == s[i] or abs(s[0] - s[i]) < tol else 1.0 if s[0] > s[i] else 0.0)
                for i in range(1, len(keys))}
        out[g["unit"]] = {"part": g["part"], "cls": g["event"][0], "right": float(right), "follow_event": float(fol[0]),
                          "follow_none": float(np.mean(fol[1:])), "conc": float(np.mean(list(pair.values()))),
                          "pair": pair}
    return out


def summarise(ev, part):
    xs = [x for x in ev.values() if x["part"] == part]
    if not xs:
        return None
    res = {"n_groups": len(xs)}
    for f in ("right", "follow_event", "follow_none", "conc"):
        res[f] = float(np.mean([x[f] for x in xs]))
    res["sound_effect"] = res["follow_event"] - res["follow_none"]
    door = ("doorbell", "knock")
    for name, sel in (("phone", lambda x: x["cls"] == "phone"), ("door", lambda x: x["cls"] in door)):
        y = [x for x in xs if sel(x)]
        if y:
            res[f"right_{name}"] = float(np.mean([x["right"] for x in y]))
            res[f"conc_{name}"] = float(np.mean([x["conc"] for x in y]))
    for v in sorted({v for x in xs for v in x["pair"]}):
        res[f"conc_1_vs_{v}"] = float(np.mean([x["pair"][v] for x in xs if v in x["pair"]]))
    return res


# ------------------------------------------------------------------------------------------------ intervals

def cluster_table(rows, split):
    T = S.unit_table(rows, {}, S.load_groups(split))
    return {u: tuple(T[u][f] for f in FACT) for u in T}


BOOT_SEED = 1          # the registered seed (B = 2000); post-fix review minor 1: other seeds only as a reported check


def boot_se(units, cl, stat, B=2000, seed=None):
    """SE of stat(w) under the plan's three-way combination (as p1v4_score.diff_variance, any statistic).
    seed None: BOOT_SEED (1, as registered; a Monte Carlo check sets other seeds and puts 1 back)."""
    fac = {f: [cl[u][i] for u in units] for i, f in enumerate(FACT)}
    rng = np.random.default_rng(BOOT_SEED if seed is None else seed)

    def var_by(keys):
        labels = ["|".join(str(fac[k][i]) for k in keys) for i in range(len(units))]
        lv = {x: j for j, x in enumerate(sorted(set(labels)))}
        idx = np.array([lv[x] for x in labels])
        w = rng.poisson(1.0, (B, len(lv)))[:, idx].astype(float)
        return float(np.var(stat(w)))

    one = {k: var_by([k]) for k in FACT}
    total = 0.0
    for r in range(1, len(FACT) + 1):
        for combo in itertools.combinations(FACT, r):
            total += (-1) ** (r + 1) * (one[combo[0]] if r == 1 else var_by(list(combo)))
    return float(np.sqrt(max(total, max(one.values())))), {k: float(np.sqrt(v)) for k, v in one.items()}


def wmean(w, x):
    return (w * x).sum(1) / np.maximum(w.sum(1), 1e-9)


def t_interval(units, cl, se, one, pt):
    """Package v0.6 15.2: point +- t(0.975, G - 1) x SE, G = clusters of the factor with the largest one-way SE among
    these units; the normal interval, the cluster counts and the dominant factor are returned beside it."""
    from scipy.stats import t as t_dist
    ncl = {f: len({cl[u][i] for u in units}) for i, f in enumerate(FACT)}
    dom = max(FACT, key=lambda f: one[f])
    df = max(ncl[dom] - 1, 1)
    tc = float(t_dist.ppf(0.975, df))
    return {"ci95": [pt - tc * se, pt + tc * se], "t_crit": tc, "df": df, "dominant_factor": dom,
            "n_clusters": ncl, "ci95_normal": [pt - 1.96 * se, pt + 1.96 * se]}


def criterion(units, cl, vals, fn, point_fn):
    """vals: {name: array over units}; fn(w) -> statistic per replicate; point_fn() -> point estimate.
    ci95 is the t interval of package v0.6 15.2 (the earlier normal interval is kept as ci95_normal)."""
    se, one = boot_se(units, cl, fn)
    pt = point_fn()
    return {"point": pt, "se": se, **t_interval(units, cl, se, one, pt), "one_way_se": one,
            "event_only_ci95": [pt - 1.96 * one["event"], pt + 1.96 * one["event"]]}


def calibrate_t(units, cl, bar=0.5, spread_sd=0.25, n_sim=200, B=400, seed=11):
    """Package v0.6 15.2: false-pass rate at the bar of a lower-bound criterion on a proportion (grounded group
    accuracy) under this cluster structure. Each simulation draws one rate per cluster of the dominant S-move factor
    ("second": the door recording group) from a Beta with mean `bar` and SD `spread_sd` (dev door groups: 0.44-0.99,
    SD about 0.25), then one Bernoulli outcome per unit; counts lower bound > bar under the t rule and the normal rule."""
    rng = np.random.default_rng(seed)
    labs = sorted({cl[u][2] for u in units})
    idx = np.array([labs.index(cl[u][2]) for u in units])
    m, v = bar, spread_sd ** 2
    k = m * (1 - m) / v - 1
    a, b = m * k, (1 - m) * k
    t_pass = n_pass = 0
    for s in range(n_sim):
        rate = rng.beta(a, b, len(labs))[idx]
        x = (rng.random(len(units)) < rate).astype(float)
        se, one = boot_se(units, cl, lambda w, x=x: wmean(w, x), B, seed + s)
        pt = float(x.mean())
        ti = t_interval(units, cl, se, one, pt)
        t_pass += ti["ci95"][0] > bar
        n_pass += ti["ci95_normal"][0] > bar
    return {"bar": bar, "spread_sd": spread_sd, "n_sim": n_sim, "B": B, "n_units": len(units),
            "n_door_groups": len(labs), "false_pass_t": t_pass / n_sim, "false_pass_normal": n_pass / n_sim,
            "nominal": 0.025}


def calibrate(units, cl, n_sim=40, B=400, seed=7, n_mc=4000):
    """Plan 7.1's two simulations on the matched R-hear units (difference of two systems' unit means)."""
    rng = np.random.default_rng(seed)
    n = len(units)
    evs = sorted({cl[u][1] for u in units})
    ev_of = np.array([evs.index(cl[u][1]) for u in units])

    def p_clu(z):
        return 1 / (1 + np.exp(-(1.4 + 0.8 * z[..., ev_of])))

    z = rng.normal(0, 1, (n_mc, len(evs)))
    est = ((rng.random((n_mc, n)) < p_clu(z)).mean(1) - (rng.random((n_mc, n)) < 0.75).mean(1))
    sd_mc = float(np.std(est))
    analytic = float(np.sqrt((0.8 * 0.2 + 0.75 * 0.25) / n))
    ind, clu = [], []
    for s in range(n_sim):
        for kind in ("ind", "clu"):
            pa = np.full(n, 0.8) if kind == "ind" else p_clu(rng.normal(0, 1, len(evs)))
            a = (rng.random(n) < pa).astype(float)
            b = (rng.random(n) < 0.75).astype(float)
            se, _ = boot_se(units, cl, lambda w, a=a, b=b: wmean(w, a) - wmean(w, b), B, seed + s)
            (ind if kind == "ind" else clu).append(se)
    return {"independent_ratio": float(np.mean(ind)) / analytic, "independent_ok_0.9_1.25":
            0.9 <= float(np.mean(ind)) / analytic <= 1.25, "clustered_ratio": float(np.mean(clu)) / sd_mc,
            "clustered_ok_0.8_1.2": 0.8 <= float(np.mean(clu)) / sd_mc <= 1.2, "n_units": n,
            "n_event_groups": len(evs), "n_sim": n_sim, "B": B}


