def word_items(rows):
    ex = S.excluded_units()
    items = []
    for r in rows:
        if r["unit"] in ex or r["part"] not in ("r_react", "s_react", "floor", "episode"):
            continue
        for p in r["points"]:
            tag = r["version"] if r["part"] in ("r_react", "s_react") else p.get("category")
            for q, gold, led, blind in WORDS.get((r["part"], tag), []):
                if p["gold"].get(q) != gold:
                    continue
                items.append({"key": (r["unit"], r["version"], p["k"]), "unit": r["unit"],
                              "type": f"{r['part']}:{tag}:{q}", "q": q, "gold": gold, "led": led, "blind": blind})
    return items


def words_channel(items, dec):
    res = collections.defaultdict(lambda: {"n": 0, "event_led": 0, "event_blind": 0, "other_wrong": 0})
    per_unit = collections.defaultdict(lambda: [0, 0, 0])            # unit: [n led-able, led errors, blind errors]
    for it in items:
        d = dec.get(it["key"], {}).get(it["q"])
        x = res[it["type"]]
        x["n"] += 1
        if d == it["gold"]:
            pass
        elif it["led"] is not None and d == it["led"]:
            x["event_led"] += 1
        elif it["blind"] is not None and d == it["blind"]:
            x["event_blind"] += 1
        else:
            x["other_wrong"] += 1
        if it["led"] is not None:
            per_unit[it["unit"]][0] += 1
            per_unit[it["unit"]][1] += int(d == it["led"])
        if it["blind"] is not None:
            per_unit[it["unit"]][2] += int(d == it["blind"])
    tot_led = sum(1 for it in items if it["led"] is not None)
    tot_blind = sum(1 for it in items if it["blind"] is not None)
    return {"by_type": dict(res),
            "event_led_rate": sum(v["event_led"] for v in res.values()) / max(1, tot_led),
            "event_blind_rate": sum(v["event_blind"] for v in res.values()) / max(1, tot_blind),
            "n_led": tot_led, "n_blind": tot_blind, "_per_unit": dict(per_unit)}


# ------------------------------------------------------------------------------------------------ measurement 3

BANDS = [(0.2, 0.5), (0.5, 0.7), (0.7, 0.9), (0.9, 0.99), (0.99, 1.01)]


def natural_points(rows, ctx):
    ex = S.excluded_units()
    pts = []
    for r in rows:
        if r["unit"] in ex or r["part"] not in ("r_hear", "s_move"):
            continue
        if r["part"] == "s_move" and r["spec"].get("visitor_speaks"):
            continue
        p = r["points"][0]
        tr, sc, tags, snd = ctx.point(r, p["k"])
        conf = max([s[3] for s in snd if RO.in_window(s, p["t"])], default=None)
        src = {s["id"]: s for s in r["sources"]}
        line = p.get("line")
        tag_ok = None
        if line and line in src and line in tags:
            tag_ok = (tags[line] == "user") == (src[line].get("who") == "user")
        pts.append({"key": (r["unit"], r["version"], p["k"]), "part": r["part"], "real": RO.is_real(r, p["t"]),
                    "conf": conf, "noise": r["spec"].get("noise"), "tag_ok": tag_ok,
                    "q": "R" if r["part"] == "r_hear" else "S", "gold": p["gold"]["R" if r["part"] == "r_hear" else "S"]})
    return pts


def bucket(p):
    c = p["conf"] if p["conf"] is not None else 0.0
    if p["real"]:
        return "event, label >= 0.9" if c >= 0.9 else "event, label 0.5-0.9" if c >= 0.5 else \
            "event, label 0.2-0.5" if c >= 0.2 else "event, no label (miss)"
    return "no event, false alarm >= 0.5" if c >= 0.5 else "no event, false alarm 0.2-0.5" if c >= 0.2 else \
        "no event, clean"


def natural_report(pts, decs):
    out = {"buckets": {}, "tags": {}, "noise": {}, "trust": {}}
    for name, dec in decs.items():
        b = collections.defaultdict(list)
        t = collections.defaultdict(list)
        nz = collections.defaultdict(list)
        for p in pts:
            ok = dec.get(p["key"], {}).get(p["q"]) == p["gold"]
            b[f"{p['part']}: {bucket(p)}"].append(ok)
            if p["tag_ok"] is not None:
                t["tag right" if p["tag_ok"] else "tag wrong"].append(ok)
            if p["part"] == "r_hear":
                nz[p["noise"]].append(ok)
        out["buckets"][name] = {k: [float(np.mean(v)), len(v)] for k, v in sorted(b.items())}
        out["tags"][name] = {k: [float(np.mean(v)), len(v)] for k, v in t.items()}
        out["noise"][name] = {k: [float(np.mean(v)), len(v)] for k, v in nz.items()}
    fa = collections.defaultdict(list)
    for p in pts:
        if p["part"] == "r_hear" and not p["real"]:
            fa[p["noise"]].append(p["conf"] is not None and p["conf"] >= 0.5)
    out["false_alarm_rate_by_noise"] = {k: [float(np.mean(v)), len(v)] for k, v in fa.items()}
    rh = [p for p in pts if p["part"] == "r_hear" and p["conf"] is not None]
    for lo, hi in BANDS:
        sel = [p for p in rh if lo <= p["conf"] < hi]
        if not sel:
            continue
        prec = float(np.mean([p["real"] for p in sel]))
        row = {"n": len(sel), "precision": prec, "step_rule_follow": prec > 0.5}
        for name, dec in decs.items():
            row[name] = float(np.mean([dec.get(p["key"], {}).get("R") == "not" for p in sel]))
        out["trust"][f"{lo:.2f}-{min(hi, 1.0):.2f}"] = row
    return out


# ------------------------------------------------------------------------------------------------ main

def main(split, do_cal=False):
    if split != "dev":                     # the v0.2 report: superseded by scripts/p1v4_grounding_v06.py (review C-minor 6)
        raise SystemExit("p1v4_grounding_report.py is the dev-only v0.2 report; use scripts/p1v4_grounding_v06.py")
    rows, rows_by = G.load(split)
    groups = G.load_groups(split)
    gunits = [g["unit"] for g in groups]
    th = thresholds(rows)
    ro = RO.load_readouts()
    pr = dict(np.load(f"{RO.OUT}/ears_probe.npz"))
    cth = json.load(open("results/main_v04/conditional_dev.json"))["thresholds"]
    ctrl = G.load_control() if "control" in th else None
    rep = json.load(open("results/main_v04/dev_report.json"))["systems"]
    res = {"split": split, "n_groups": collections.Counter(g["part"] for g in groups), "thresholds":
           {k: v for k, v in th.items() if not k.startswith("_")}, "missing": [], "identity": {}, "noise_floor": {},
           "m1": {}, "m4": {}, "criteria": {}}
    if "_control_op" in th:
        res["control_dev_operating_point"] = {k: th["_control_op"][k] for k in ("primary", "floors_met", "parts")}
    ev_all = {}                        # (system, cond) -> group eval
    l1_runs = {}
    for cond in G.CONDS:
        l1, extra = l1_scores(split, cond, ro, pr, cth, ctrl)
        loc = local_scores(split, cond)
        api = api_scores(split, cond, groups, rows_by) if cond != "natural" else {}
        if l1 is None:
            res["missing"].append(f"l1 {cond}")
            continue
        l1_runs[cond] = extra
        scores = dict(l1)
        if loc is not None:
            scores.update({n: loc[n] for n in ("T", "L2", "L3")})
            comb, _ = CP.combine(l1["old head"], loc["L3"], "logit", 0.5)
            scores["combination"] = comb
        else:
            res["missing"].append(f"local {cond}")
        scores.update(api)
        for name, sc in scores.items():
            if name not in th:
                continue
            dec = S.decide(sc, *th[name])
            ev_all[(name, cond)] = group_eval(groups, rows_by, dec, sc)
        if loc is not None:
            ev_all[("B1-strong", cond)] = group_eval(groups, rows_by, loc["B1-strong"])
        probe_sc = {k: {"R": 1 - p, "S": p} for k, p in extra["probe"].items()}
        ev_all[("ears probe", cond)] = group_eval(groups, rows_by, S.decide(probe_sc, 0.5, 0.5), probe_sc)
        # identity (4.5)
        if cond != "natural":
            z = extra["z"]
            sh = collections.defaultdict(set)
            for idv, h in zip(z["ids"], z["text_sha"]):
                sh[idv.split("|")[0]].add(str(h))
            bad_l1 = sorted(u for u, s in sh.items() if len(s) > 1)
            bad_loc = []
            if loc is not None:
                shl = collections.defaultdict(set)
                for k, h in loc["_sha"].items():
                    shl[k.split("|")[0]].add(h)
                bad_loc = sorted(u for u, s in shl.items() if len(s) > 1)
                b1 = collections.defaultdict(set)
                for k, d in loc["B1-strong"].items():
                    b1[k[0]].add(json.dumps(d, sort_keys=True))
                b1_differ = sum(1 for s in b1.values() if len(s) > 1)
            else:
                b1_differ = None
            api_bad = {}
            for name, sd in API.items():
                p = os.path.join(G.out_dir(split), "api", sd, G.SETTINGS[sd], cond, "case_sha.json")
                if os.path.exists(p):
                    cs = json.load(open(p))
                    sa = collections.defaultdict(set)
                    for k, h in cs.items():
                        sa[k.split("|")[0]].add(h)
                    api_bad[name] = sum(1 for s in sa.values() if len(s) > 1)
            res["identity"][cond] = {"l1_text_groups_differ": len(bad_l1), "local_non_audio_groups_differ":
                                     len(bad_loc), "b1_decisions_groups_differ": b1_differ, "api_case_groups_differ":
                                     api_bad, "n_groups": len(groups)}
    # noise floor (4.6)
    if "natural" in l1_runs:
        stored = keyed(json.load(open(f"{R}/l1/scores_dev.json")))
        new = RO.scores_of(l1_runs["natural"]["z"], None, ro)
        diffs = [abs(stored[k][q] - v) for k, d in new.items() for q, v in d.items() if k in stored]
        a, b = S.decide(stored, *th["old head"]), S.decide(new, *th["old head"])
        flips = sum(1 for k in new for q in new[k] if a.get(k, {}).get(q) != b[k][q])
        res["noise_floor"]["old head"] = {"max_abs_diff": float(max(diffs)), "median_abs_diff":
                                          float(np.median(diffs)), "decision_flips": flips, "n": len(diffs)}
        zst = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
        for name, setting in (("read-out", "ears"), ("states read-out", "states")):
            s_old = RO.scores_of(zst, setting, ro)
            s_new = RO.scores_of(l1_runs["natural"]["z"], setting, ro)
            a, b = S.decide(s_old, *th[name]), S.decide(s_new, *th[name])
            flips = sum(1 for k in s_new for q in s_new[k] if a.get(k, {}).get(q) != b[k][q])
            res["noise_floor"][name] = {"max_abs_diff": float(max(abs(s_old[k][q] - v) for k, d in s_new.items()
                                                                  for q, v in d.items())), "decision_flips": flips}
    loc_nat = local_scores(split, "natural")
    if loc_nat is not None:
        for n, d in (("T", "t"), ("L2", "l2"), ("L3", "l3")):
            stored = keyed(json.load(open(f"{R}/{d}/scores_dev.json")))
            new = loc_nat[n]
            res["noise_floor"][n] = {"max_abs_diff": float(max(abs(stored[k][q] - v) for k, dd in new.items()
                                                               for q, v in dd.items()))}
        stored = keyed(json.load(open(f"{R}/b1/decisions_dev.json")))
        res["noise_floor"]["B1-strong"] = {"decision_differences": sum(1 for k, d in loc_nat["B1-strong"].items()
                                                                       if stored.get(k) != d)}
    # measurement 1
    names = sorted({n for n, _ in ev_all})
    for name in names:
        res["m1"][name] = {}
        for part in ("r_hear", "s_move"):
            per = {cond: summarise(ev_all[(name, cond)], part) for cond in G.CONDS if (name, cond) in ev_all}
            per = {c: v for c, v in per.items() if v is not None}
            matched = [per[c] for c in G.MATCHED if c in per]
            res["m1"][name][part] = {"by_condition": per, "n_matched_conditions": len(matched),
                                     "mean_matched": {f: float(np.mean([m[f] for m in matched]))
                                                      for f in ("right", "conc", "follow_event", "follow_none",
                                                                "sound_effect")} if matched else None}
    # measurement 4: hard subset (natural rerun), conflicts
    if "natural" in l1_runs:
        hard = {q["key"]: q["real"] for q in TC.r_hear_points(rows, C.Context(split))
                if q["conf"] is not None and 0.5 <= q["conf"] < 0.9}
        l1n, _ = l1_scores(split, "natural", ro, pr, cth, ctrl)
        hk = [k for k in hard if k in l1n["old head"]]
        y = np.array([hard[k] for k in hk])
        res["m4"]["hard_subset"] = {"n_real": int(y.sum()), "n_false": int(len(y) - y.sum())}
        for name, sc in l1n.items():
            res["m4"]["hard_subset"][name] = float(roc_auc_score(y, [1 - sc[k]["R"] for k in hk]))
        res["m4"]["hard_subset"]["ears probe"] = float(roc_auc_score(y, [l1_runs["natural"]["probe"][k] for k in hk]))
    conflicts = {}
    for cond in G.MATCHED:
        if cond not in l1_runs:
            continue
        z, probe = l1_runs[cond]["z"], l1_runs[cond]["probe"]
        l1c, _ = l1_scores(split, cond, ro, pr, cth, ctrl)
        for name, sc in l1c.items():
            dec = S.decide(sc, *th[name])
            agree_e, agree_l, n = 0, 0, 0
            for w, idv in enumerate(z["ids"]):
                u, v, k = idv.split("|")
                key = (u, v, int(k))
                part = z["parts"][w]
                q, ev = event_value(part)
                heard = probe[key] >= 0.5
                says = z["conf"][w] >= 0.9
                if heard == says or q not in dec.get(key, {}):
                    continue
                act = dec[key][q] == ev
                n += 1
                agree_e += int(act == heard)
                agree_l += int(act == says)
            x = conflicts.setdefault(name, [0, 0, 0])
            x[0] += n
            x[1] += agree_e
            x[2] += agree_l
    res["m4"]["conflicts"] = {k: {"n": v[0], "with_ears": v[1] / max(1, v[0]), "with_label": v[2] / max(1, v[0])}
                              for k, v in conflicts.items()}
    # criteria (9.2), R-hear, mean over the matched conditions
    cl = cluster_table(rows, split)
    rh = [u for u in gunits if any(g["unit"] == u and g["part"] == "r_hear" for g in groups)]

    def unit_vals(name, field):
        conds = [c for c in G.MATCHED if (name, c) in ev_all]
        if len(conds) < len(G.MATCHED):
            return None
        return np.array([np.mean([ev_all[(name, c)][u][field] for c in conds]) for u in rh])

    crit = {}
    for cand in CANDIDATES:
        a = unit_vals(cand, "right")
        if a is None:
            continue
        crit[f"G1a {cand}: grounded group accuracy (lower bound > 0.50)"] = criterion(
            rh, cl, {}, lambda w, a=a: wmean(w, a), lambda a=a: float(a.mean()))
        b3 = unit_vals("B3", "conc")
        c = unit_vals(cand, "conc")
        if b3 is not None:
            crit[f"G1b {cand} - B3: concordance (>= 0.20, CI > 0)"] = criterion(
                rh, cl, {}, lambda w, c=c, b=b3: wmean(w, c) - wmean(w, b), lambda c=c, b=b3: float(c.mean() - b.mean()))
    new, old, ctl = unit_vals("states read-out", "conc"), unit_vals("old head", "conc"), unit_vals("control", "conc")
    if new is not None and old is not None:
        crit["G2a (states - 0.5) - |old head - 0.5| (>= 0.20, CI > 0)"] = criterion(
            rh, cl, {}, lambda w: (wmean(w, new) - 0.5) - np.abs(wmean(w, old) - 0.5),
            lambda: float((new.mean() - 0.5) - abs(old.mean() - 0.5)))
    if new is not None and ctl is not None:
        crit["G2b states - natural-label control (>= 0.20, CI > 0)"] = criterion(
            rh, cl, {}, lambda w: wmean(w, new) - wmean(w, ctl), lambda: float(new.mean() - ctl.mean()))
    for k, v in crit.items():
        if k.startswith("G1a"):
            v["pass"] = v["ci95"][0] > 0.5
        else:
            v["pass"] = v["point"] >= G_MARGIN and v["ci95"][0] > 0
    res["criteria"] = crit
    if do_cal:
        res["calibration"] = calibrate(rh, cl)
    # measurement 2 and 3 (natural, stored dev outputs)
    if split == "dev":
        nat = {"old head": S.decide(keyed(json.load(open(f"{R}/l1/scores_dev.json"))), *th["old head"]),
               "read-out": S.decide(keyed(json.load(open(f"{RO.OUT}/scores_dev_readout.json"))), *th["read-out"]),
               "conditional": S.decide(keyed(json.load(open(f"{RO.OUT}/scores_dev_conditional.json"))), 0.5, 0.5),
               "combination": S.decide(keyed(json.load(open(f"{RO.OUT}/scores_dev_combination.json"))),
                                       *th["combination"])}
        zst = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
        nat["states read-out"] = S.decide(RO.scores_of(zst, "states", ro), *th["states read-out"])
        for n, d in (("L3", "l3"), ("L2", "l2"), ("T", "t")):
            nat[n] = S.decide(keyed(json.load(open(f"{R}/{d}/scores_dev.json"))), *th[n])
        nat["B1-strong"] = keyed(json.load(open(f"{R}/b1/decisions_dev.json")))
        for n, sc in natural_api(rep).items():
            nat[n] = S.decide(sc, *th[n])
        items = word_items(rows)
        wc = {n: words_channel(items, d) for n, d in nat.items()}
        T = S.unit_table(rows, {}, S.load_groups(split))
        cmp = {}
        for a_, b_ in (("read-out", "old head"), ("conditional", "old head"), ("combination", "old head")):
            pa, pb = wc[a_]["_per_unit"], wc[b_]["_per_unit"]
            us = sorted(u for u in pa if pa[u][0] > 0 and u in T)
            n_ = np.array([pa[u][0] for u in us], float)
            ea = np.array([pa[u][1] for u in us], float)
            eb = np.array([pb.get(u, [0, 0, 0])[1] for u in us], float)
            clw = {u: tuple(T[u][f] for f in FACT) for u in us}
            se, one = boot_se(us, clw, lambda w: (w * ea).sum(1) / (w * n_).sum(1) - (w * eb).sum(1) / (w * n_).sum(1))
            pt = float(ea.sum() / n_.sum() - eb.sum() / n_.sum())
            cmp[f"{a_} - {b_}: event-led error rate"] = {"point": pt, "se": se, "ci95": [pt - 1.96 * se, pt + 1.96 * se]}
        res["m2"] = {"by_system": {n: {k: v for k, v in x.items() if not k.startswith("_")} for n, x in wc.items()},
                     "paired": cmp}
        pts = natural_points(rows, C.Context(split))
        res["m3"] = natural_report(pts, nat)
    os.makedirs("results/main_v04", exist_ok=True)
    json.dump(res, open(f"results/main_v04/grounding_{split}.json", "w"), indent=1, default=str)
    show(res)


def show(res):
    print("missing:", res["missing"])
    print("identity (groups whose versions differ):", json.dumps(res["identity"]))
    print("noise floor:", json.dumps(res["noise_floor"]))
    for name, x in res["m1"].items():
        for part in ("r_hear", "s_move"):
            m = x[part]["mean_matched"]
            if m is None:
                continue
            curve = " ".join(f"{c}:{x[part]['by_condition'][c]['right']:.2f}/{x[part]['by_condition'][c]['conc']:.2f}"
                             for c in x[part]["by_condition"])
            print(f"M1 {name:16s} {part:7s} matched mean: grounded {m['right']:.3f} conc {m['conc']:.3f} "
                  f"follow event {m['follow_event']:.2f} none {m['follow_none']:.2f} | per cond right/conc {curve}")
    if res["m4"]:
        print("M4 hard subset AUC:", json.dumps(res["m4"].get("hard_subset")))
        print("M4 conflicts:", json.dumps(res["m4"].get("conflicts")))
    for k, v in res["criteria"].items():
        print(f"{k}: {v['point']:+.3f} [{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}] pass={v['pass']}")
    if "calibration" in res:
        print("calibration:", json.dumps(res["calibration"]))
    if "m2" in res:
        for n, x in res["m2"]["by_system"].items():
            print(f"M2 {n:16s} event-led {x['event_led_rate']:.3f} (n {x['n_led']}), event-blind "
                  f"{x['event_blind_rate']:.3f} (n {x['n_blind']})")
        for k, v in res["m2"]["paired"].items():
            print(f"M2 {k}: {v['point']:+.3f} [{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}]")
    if "m3" in res:
        print("M3 trust:", json.dumps(res["m3"]["trust"]))


if __name__ == "__main__":
    main(sys.argv[1], "--calibrate" in sys.argv)
